<?php
declare(strict_types=1);
require_once __DIR__ . '/lib.php';
require_admin();
function admin_datetime_local(?string $iso): string { try { return $iso ? (new DateTimeImmutable($iso))->setTimezone(new DateTimeZone(APP_TIMEZONE))->format('Y-m-d\TH:i') : ''; } catch (Throwable) { return ''; } }
$data = api_request('admin_status', [], true);
$maintenance = is_array($data['maintenance'] ?? null) ? $data['maintenance'] : [];
$csrf = csrf_token();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><?php render_head_meta('Maintenance — The Secretary Control Room','Create and manage maintenance pages.','admin/maintenance',true); ?><link rel="stylesheet" href="/assets/style.css?v=3.0.0"></head>
<body class="admin-body"><?php render_admin_header('maintenance'); ?><main class="container wide admin-page">
<div class="admin-intro"><div><span class="eyebrow">Planned work</span><h1>Maintenance.</h1><p>Schedule, alter, conclude, or permanently remove maintenance pages.</p></div></div><?php render_admin_nav('maintenance'); render_admin_flash(); ?>
<div class="admin-grid">
  <section class="panel span-5"><div class="panel-heading"><div><span class="eyebrow">New window</span><h2>Schedule maintenance</h2></div></div><form action="/action" method="post" class="stack-form" data-editor-form><input type="hidden" name="csrf" value="<?= h($csrf) ?>"><input type="hidden" name="return_to" value="/admin/maintenance"><input type="hidden" name="action" value="create_maintenance"><label>Title<input name="title" data-slug-title maxlength="120" required></label><label>Slug<input name="slug" data-slug-input pattern="[a-z0-9][a-z0-9-]{0,119}"></label><div class="split-fields"><label>Starts<input name="start_at" type="datetime-local" required></label><label>Ends<input name="end_at" type="datetime-local" required></label></div><label>Description<textarea name="description" rows="4" maxlength="3000" required></textarea></label><label>Full maintenance page</label><?php render_rich_editor('content_html'); ?><div class="form-actions"><button class="button primary" type="submit">Schedule maintenance</button></div></form></section>
  <section class="panel span-7"><div class="panel-heading"><div><span class="eyebrow">Page management</span><h2>Maintenance windows</h2></div><span><?= count($maintenance) ?> total</span></div><div class="manage-list"><?php if (!$maintenance): ?><div class="empty-card">No maintenance pages yet.</div><?php else: foreach ($maintenance as $item): ?><article class="manage-item"><div class="manage-summary"><div><span class="status-pill maint"><?= h(ucfirst((string) ($item['status'] ?? 'scheduled'))) ?></span><h3><?= h((string) ($item['title'] ?? 'Maintenance')) ?></h3><p><?= h(format_time($item['startAt'] ?? null)) ?> → <?= h(format_time($item['endAt'] ?? null)) ?></p></div><a class="button small ghost" href="/maintenance/<?= h((string) ($item['slug'] ?? '')) ?>" target="_blank" rel="noopener">Open ↗</a></div><div class="manage-actions"><?php if (in_array(($item['status'] ?? ''),['scheduled','active'],true)): ?><form action="/action" method="post"><input type="hidden" name="csrf" value="<?= h($csrf) ?>"><input type="hidden" name="return_to" value="/admin/maintenance"><input type="hidden" name="action" value="cancel_maintenance"><input type="hidden" name="id" value="<?= h((string) ($item['id'] ?? '')) ?>"><button class="button small danger" type="submit">Conclude / cancel</button></form><?php endif; ?><form action="/action" method="post" data-confirm="Permanently delete this maintenance page?"><input type="hidden" name="csrf" value="<?= h($csrf) ?>"><input type="hidden" name="return_to" value="/admin/maintenance"><input type="hidden" name="action" value="delete_maintenance"><input type="hidden" name="id" value="<?= h((string) ($item['id'] ?? '')) ?>"><button class="button small danger" type="submit">Delete page</button></form></div><details><summary>Edit schedule and page</summary><form action="/action" method="post" class="stack-form" data-editor-form><input type="hidden" name="csrf" value="<?= h($csrf) ?>"><input type="hidden" name="return_to" value="/admin/maintenance"><input type="hidden" name="action" value="edit_maintenance"><input type="hidden" name="id" value="<?= h((string) ($item['id'] ?? '')) ?>"><div class="split-fields"><label>Title<input name="title" value="<?= h((string) ($item['title'] ?? '')) ?>" required></label><label>Slug<input name="slug" value="<?= h((string) ($item['slug'] ?? '')) ?>" required></label></div><div class="split-fields"><label>Starts<input name="start_at" type="datetime-local" value="<?= h(admin_datetime_local($item['startAt'] ?? null)) ?>" required></label><label>Ends<input name="end_at" type="datetime-local" value="<?= h(admin_datetime_local($item['endAt'] ?? null)) ?>" required></label></div><label>Description<textarea name="description" rows="3" required><?= h((string) ($item['description'] ?? $item['excerpt'] ?? '')) ?></textarea></label><?php render_rich_editor('content_html',(string)($item['contentHtml'] ?? '')); ?><button class="button primary" type="submit">Save maintenance</button></form></details></article><?php endforeach; endif; ?></div></section>
